package com.example.riskplatform.service;import com.example.riskplatform.mapper.CompanyScopeMapper;import com.example.riskplatform.security.CurrentUserService;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.util.*;
@Service @RequiredArgsConstructor public class DataScopeService{private final CurrentUserService current;private final CompanyScopeMapper mapper;public List<Long>allowedCompanyIds(){return switch(current.dataScope()){case "ALL","ALL_READONLY"->null;case "DEPT_AND_CHILD"->mapper.selectIdsByDeptTree(current.deptId());case "DEPT"->mapper.selectIdsByDept(current.deptId());default->mapper.selectIdsByOwner(current.userId());};}public boolean canAccess(Long id){List<Long>x=allowedCompanyIds();return x==null||x.contains(id);}}
